INSERT INTO `EmailTemplate` (`id`, `key`, `subject`, `body`, `updatedAt`, `name`) VALUES
(1, 'customer_confirmation', 'Your Graduation Cap Order Confirmation - {{orderNumber}}', 'Dear {{customerName}},\n\nThank you for your order! Your graduation cap design has been received.\n\nOrder Number: {{orderNumber}}\nTotal: {{totalPrice}} {{currency}}\n\nYour cap design images (Front, Back, Top, Bottom) are attached to this email.\n\nBest regards,\nStudentLife Team', '2026-08-13 09:05:08.845', NULL),
(2, 'manufacturer_production', 'Weekly Production Batch - {{orderCount}} Orders', 'Hello,\n\nPlease find attached this week\'s production batch containing {{orderCount}} graduation cap orders.\n\nExcel file and individual PDFs are included.\n\nBest regards,\nStudentLife Production', '2026-08-13 09:05:10.500', NULL),
(3, 'order-delivered', 'Your Graduation Cap Order is Delivered - {{orderNumber}}', 'Dear {{customerName}},\n\nGreat news! Your graduation cap order has been successfully delivered.\n\nOrder Number: {{orderNumber}}\n\nWe hope you are happy with your custom graduation cap and that it makes your graduation day even more special.\n\nThank you for choosing StudentLife. We appreciate your trust and wish you all the best for your future!\n\nBest regards,\nStudentLife Team\n', '2026-08-03 10:23:49.098', 'Order Delivered'),
(4, 'ordre-sendt-til-produktion', 'Din studenterhue er nu i produktion 🎓', 'Hej {{customerName}},\n\nFantastiske nyheder! 🎉\n\nDin studenterhue er nu sendt til produktion.\n\nVores team er gået i gang med at fremstille netop din hue ud fra de valg, du har lavet. Nu er der ikke længe, før den er klar til at blive en del af din store dag.\n\nVi holder dig selvfølgelig opdateret undervejs og sender dig en ny mail, så snart der er nyt om din ordre.\n\nTak fordi du har valgt StudentLife – vi glæder os til at være en del af din studenterrejse! 🎓\n\nDe bedste hilsner\nStudentLife Team', '2026-08-03 20:21:21.221', 'Ordre sendt til produktion');

