CREATE TABLE `OrderStatus` (
  `id` int(11) NOT NULL,
  `name` varchar(191) NOT NULL,
  `slug` varchar(191) NOT NULL,
  `sortOrder` int(11) NOT NULL DEFAULT 0,
  `isInternal` tinyint(1) NOT NULL DEFAULT 0,
